import React, { useEffect, useMemo, useRef, useState } from 'react';
import {
  Archive, BookOpen, Bot, CheckCircle2, ChevronLeft, ChevronRight, CircleAlert,
  Clock3, Download, ExternalLink, FileEdit, FileSearch, History, LibraryBig,
  Plus, RefreshCw, Save, Search, ShieldCheck, Trash2, X,
} from 'lucide-react';
import { blogAdminGet, blogAdminPost, fetchEditorialDraft, generateEditorialDraft } from './api';
import { BlogGscStatus } from './BlogGscStatus';
import { BlogPublicationStatus } from './BlogPublicationStatus';

type BlogSection='overview'|'articles'|'generate'|'review'|'automations';
const SECTIONS:{id:BlogSection;label:string;icon:React.ComponentType<{size?:number}>}[]=[
  {id:'overview',label:'Visão geral',icon:BookOpen},{id:'articles',label:'Artigos e acervo',icon:LibraryBig},{id:'generate',label:'Gerar artigo',icon:Bot},{id:'review',label:'Revisão',icon:ShieldCheck},{id:'automations',label:'Automações',icon:Clock3},
];
const STATUS_LABELS:Record<string,string>={inventario:'Inventário',briefing:'Briefing',rascunho:'Rascunho',revisao_editorial:'Revisão editorial',revisao_clinica:'Revisão clínica',aprovado:'Aprovado, aguardando publicação',publicado:'Publicado',arquivado:'Arquivado'};
const blockTypes=[['p','Parágrafo'],['h2','Título de seção'],['h3','Subtítulo'],['ul','Lista'],['ol','Lista numerada'],['quote','Citação']];

function formatDate(value?:string|null){if(!value)return 'Indisponível';const d=new Date(value);return Number.isNaN(d.getTime())?'Indisponível':new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(d);}
function countValue(value:unknown){return typeof value==='number'?String(value):'Indisponível';}
function signature(value:unknown){const text=JSON.stringify(value);let h=2166136261;for(let i=0;i<text.length;i++){h^=text.charCodeAt(i);h=Math.imul(h,16777619);}return (h>>>0).toString(16);}
function persistentOperation(scope:string,payload:unknown,forceNew=false){const key=`karyne_blog_op:${scope}`;const sig=signature(payload);if(!forceNew){try{const old=JSON.parse(localStorage.getItem(key)||'null');if(old?.signature===sig&&old?.operationKey)return old.operationKey;}catch{/* ignore */}}const operationKey=crypto.randomUUID();localStorage.setItem(key,JSON.stringify({signature:sig,operationKey}));return operationKey;}
function clearOperation(scope:string){localStorage.removeItem(`karyne_blog_op:${scope}`);}
function updateBlogSection(section:BlogSection){const url=new URL(window.location.href);url.searchParams.set('tab','blog');url.searchParams.set('blogSection',section);history.replaceState({},'',url);}

const StatusPill:React.FC<{status?:string|null}>=({status})=><span className="inline-flex rounded-full bg-[#565E48]/10 border border-[#565E48]/15 px-2 py-1 text-[11px] font-medium text-[#46503B]">{status?STATUS_LABELS[status]||status:'Indisponível'}</span>;
const Notice:React.FC<{type?:'error'|'ok'|'info';children:React.ReactNode}>=({type='info',children})=><div className={`rounded-xl border p-3 text-sm ${type==='error'?'border-[#8B2312]/20 bg-[#8B2312]/8 text-[#8B2312]':type==='ok'?'border-[#365B32]/20 bg-[#365B32]/8 text-[#365B32]':'border-[#D8D1C9] bg-white text-[#2B1B0A]/70'}`}>{children}</div>;

function PreviewArticle({article,presentation}:{article:any;presentation:any}){
  const [html,setHtml]=useState('');const [error,setError]=useState('');const [loading,setLoading]=useState(true);
  const request=JSON.stringify({article,presentation});
  useEffect(()=>{let active=true;setLoading(true);setError('');setHtml('');const timeout=window.setTimeout(()=>{void blogAdminPost({action:'preview',...JSON.parse(request)}).then(result=>{if(!active)return;if(typeof result.html!=='string')throw new Error('Prévia indisponível');setHtml(result.html);}).catch(e=>{if(active)setError(e instanceof Error?e.message:'Prévia indisponível');}).finally(()=>{if(active)setLoading(false);});},250);return()=>{active=false;window.clearTimeout(timeout);};},[request]);
  return <section className="bg-white border border-[#E4DFD9] rounded-2xl overflow-hidden"><div className="px-4 py-2 text-[11px] text-[#565E48]">Prévia privada · não publicada</div>{loading?<Notice>Preparando prévia…</Notice>:error?<Notice type="error">{error}</Notice>:<iframe title="Prévia privada do artigo" sandbox="" srcDoc={html} className="w-full min-h-[680px] border-0"/>}</section>;
}

function useModalAccessibility(onClose:()=>void){
  const close=useRef(onClose);close.current=onClose;
  useEffect(()=>{const trigger=document.activeElement as HTMLElement|null;document.querySelector<HTMLElement>('[role="dialog"]')?.focus();const key=(event:KeyboardEvent)=>{const modal=document.querySelector<HTMLElement>('[role="dialog"]');if(event.key==='Escape'){event.preventDefault();close.current();}if(event.key==='Tab'&&modal){const elements=Array.from(modal.querySelectorAll<HTMLElement>('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),summary,iframe,[tabindex="0"]'));const first=elements[0],last=elements[elements.length-1];if(event.shiftKey&&(document.activeElement===first||document.activeElement===modal||!modal.contains(document.activeElement))){event.preventDefault();last?.focus();}else if(!event.shiftKey&&(document.activeElement===last||document.activeElement===modal||!modal.contains(document.activeElement))){event.preventDefault();first?.focus();}}};document.addEventListener('keydown',key);return()=>{document.removeEventListener('keydown',key);trigger?.focus();};},[]);
}

function BlockEditor({body,onChange}:{body:any[];onChange:(body:any[])=>void}){
  const patch=(index:number,patch:any)=>onChange(body.map((b,i)=>i===index?{...b,...patch}:b));
  return <div className="space-y-3">{body.map((block,index)=><div key={index} className="rounded-xl border border-[#E4DFD9] bg-[#FAF8F4] p-3"><div className="flex gap-2 items-center"><select aria-label="Tipo de bloco" value={block.type} onChange={e=>{const type=e.target.value;patch(index,type==='ul'||type==='ol'?{type,items:block.items||[block.text||''],text:undefined}:{type,text:block.text||(block.items||[]).join(' '),items:undefined});}} className="rounded-lg border border-[#D8D1C9] bg-white px-2 py-2 text-sm">{blockTypes.map(([value,label])=><option key={value} value={value}>{label}</option>)}</select><button onClick={()=>onChange(body.filter((_,i)=>i!==index))} className="ml-auto p-2 text-[#8B2312]" title="Remover bloco"><Trash2 size={15}/></button></div>{block.type==='ul'||block.type==='ol'?<textarea aria-label="Itens da lista" value={(block.items||[]).join('\n')} onChange={e=>patch(index,{items:e.target.value.split('\n')})} rows={4} className="mt-2 w-full rounded-lg border border-[#D8D1C9] p-2 text-sm" placeholder="Um item por linha"/>:<textarea aria-label="Texto do bloco" value={block.text||''} onChange={e=>patch(index,{text:e.target.value})} rows={block.type==='p'?4:2} className="mt-2 w-full rounded-lg border border-[#D8D1C9] p-2 text-sm"/>}</div>)}<button onClick={()=>onChange([...body,{type:'p',text:''}])} className="inline-flex items-center gap-1 text-sm px-3 py-2 rounded-xl border border-[#D8D1C9] bg-white"><Plus size={14}/>Adicionar bloco</button></div>;
}

function ArticleDetail({articleId,onClose,onSaved}:{articleId:string;onClose:()=>void;onSaved?:()=>void}){
  useModalAccessibility(onClose);
  const [data,setData]=useState<any>(null);const [mode,setMode]=useState<'preview'|'edit'|'history'|'sources'>('preview');const [form,setForm]=useState<any>(null);const [loading,setLoading]=useState(true);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [notice,setNotice]=useState('');const [sourceDetail,setSourceDetail]=useState<any>(null);
  const load=async()=>{setLoading(true);setError('');try{const json=await blogAdminGet({view:'article',id:articleId});setData(json);const latest=json.detail.versions?.[0];const payload=latest?.content_payload_json||{};setForm({title:payload.title||latest?.title||json.detail.article.working_title,description:payload.description||latest?.description||'',slug:json.detail.article.target_slug,body:payload.body||latest?.body_json||[],ctaLabel:payload.ctaLabel||'Conhecer a avaliação inicial',internalLinks:payload.internalLinks||[],references:payload.references||latest?.references_json||[],presentation:latest?.presentation_payload_json||{kind:'none',subject:'sem-imagem-adequada',reason:'Selecione uma apresentação antes de salvar',image:null},changeNote:''});}catch(e){setError(e instanceof Error?e.message:'Falha ao abrir artigo');}finally{setLoading(false);}};
  useEffect(()=>{void load();},[articleId]);
  if(loading||(!data&&error))return <div role="dialog" aria-modal="true" aria-label="Artigo privado" tabIndex={-1} className="fixed inset-0 z-50 bg-black/35 p-4"><div className="max-w-4xl mx-auto rounded-2xl bg-[#F6F0E9] p-5"><Notice type={error?'error':'info'}>{error||'Carregando artigo…'}</Notice><button onClick={onClose} className="mt-3 rounded-xl border border-[#D8D1C9] px-3 py-2">Fechar</button></div></div>;
  const detail=data?.detail;const latest=detail?.versions?.[0];const published=detail?.publications?.find((p:any)=>p.publication_status==='published');const publicVersion=published?detail.versions.find((v:any)=>v.id===published.article_version_id):null;
  const save=async()=>{setBusy(true);setError('');setNotice('');try{const payload={action:'save-version',articleId,expectedVersionId:latest.id,expectedVersionNumber:latest.version_number,article:form,changeNote:form.changeNote};const operationKey=persistentOperation(`save:${articleId}:${latest.id}`,payload);await blogAdminPost({...payload,operationKey});clearOperation(`save:${articleId}:${latest.id}`);setNotice('Nova versão salva. Ela precisa ser aprovada de novo, e o que está no site não mudou.');await load();onSaved?.();}catch(e){setError(e instanceof Error?e.message:'Falha ao salvar');}finally{setBusy(false);}};
  const exportSnapshot=async()=>{setBusy(true);setError('');try{const json=await blogAdminPost({action:'export-snapshot',articleId,versionId:latest.id});const blob=new Blob([JSON.stringify(json.snapshot,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`blog-${json.snapshot.article.slug}-v${json.snapshot.article.version}.json`;a.click();URL.revokeObjectURL(url);setNotice('Arquivo da versão aprovada baixado. Isso não publica nem muda o artigo no site.');}catch(e){setError(e instanceof Error?e.message:'Falha ao exportar');}finally{setBusy(false);}};
  const setPresentation=(value:string)=>{if(value==='none')setForm((f:any)=>({...f,presentation:{kind:'none',reviewStatus:'reviewed',subject:'sem-imagem-adequada',reason:f.presentation?.reason||'',image:null}}));else{const asset=data.assets.find((a:any)=>a.file===value);setForm((f:any)=>({...f,presentation:{kind:'image',reviewStatus:'reviewed',subject:asset.label,image:{file:asset.file,label:asset.label,alt:asset.defaultAlt,caption:asset.defaultCaption||''}}}));}};
  const openSource=async(id:string)=>{setError('');try{const json=await blogAdminGet({view:'source',id});setSourceDetail(json.source);}catch(e){setError(e instanceof Error?e.message:'Falha ao abrir fonte');}};
  return <div role="dialog" aria-modal="true" aria-label="Artigo privado" tabIndex={-1} className="fixed inset-0 z-50 bg-black/35 p-3 md:p-6 overflow-y-auto"><div className="max-w-6xl mx-auto bg-[#F6F0E9] min-h-[90vh] rounded-2xl shadow-xl border border-[#D8D1C9] overflow-hidden"><div className="sticky top-0 z-10 bg-[#F6F0E9]/95 backdrop-blur border-b border-[#D8D1C9] p-4 flex items-center gap-3"><div><div className="font-serif text-xl text-[#222D19]">{detail.article.working_title}</div><div className="text-[12px] text-[#2B1B0A]/50">Trabalho v{latest?.version_number??'—'} · público v{publicVersion?.version_number??'nenhum'} · {STATUS_LABELS[detail.article.status]||detail.article.status}</div></div><button aria-label="Fechar artigo" onClick={onClose} className="ml-auto p-2 rounded-xl border border-[#D8D1C9] bg-white"><X size={17}/></button></div>
    <div className="p-4 md:p-6"><div className="flex flex-wrap gap-2 mb-5">{(['preview','edit','history','sources'] as const).map(item=><button key={item} onClick={()=>setMode(item)} className={`px-3 py-2 rounded-xl text-sm ${mode===item?'bg-[#222D19] text-white':'bg-white border border-[#D8D1C9]'}`}>{item==='preview'?'Prévia':item==='edit'?'Editar':item==='history'?'Versões e revisões':'Fontes'}</button>)}{published?.canonical_url&&<a href={published.canonical_url} target="_blank" rel="noreferrer" className="ml-auto inline-flex items-center gap-1 px-3 py-2 rounded-xl border border-[#D8D1C9] bg-white text-sm">Ver versão pública <ExternalLink size={14}/></a>}</div>
    {error&&<div className="mb-4"><Notice type="error">{error}</Notice></div>}{notice&&<div className="mb-4"><Notice type="ok">{notice}</Notice></div>}
    {mode==='preview'&&<PreviewArticle article={form} presentation={form.presentation}/>}
    {mode==='edit'&&<div className="grid grid-cols-1 lg:grid-cols-[1fr_320px] gap-5"><div className="space-y-5"><section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><label className="text-[11px] uppercase text-[#2B1B0A]/45">Título</label><input aria-label="Título do artigo" value={form.title} onChange={e=>setForm({...form,title:e.target.value})} className="mt-1 w-full border border-[#D8D1C9] rounded-xl px-3 py-2.5"/><label className="block mt-4 text-[11px] uppercase text-[#2B1B0A]/45">Descrição</label><textarea aria-label="Descrição do artigo" value={form.description} onChange={e=>setForm({...form,description:e.target.value})} rows={3} className="mt-1 w-full border border-[#D8D1C9] rounded-xl px-3 py-2.5"/><div className="mt-4 text-[11px] text-[#2B1B0A]/45">Endereço (não muda depois de criado): <code>/blog/{form.slug}/</code></div></section><section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="font-medium text-sm mb-3">Conteúdo</div><BlockEditor body={form.body} onChange={body=>setForm({...form,body})}/></section><section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="font-medium text-sm mb-3">Referências</div>{form.references.map((ref:any,i:number)=><div key={i} className="grid grid-cols-1 md:grid-cols-2 gap-2 mb-2"><input aria-label="Título da referência" value={ref.title||''} onChange={e=>setForm({...form,references:form.references.map((r:any,j:number)=>j===i?{...r,title:e.target.value}:r)})} placeholder="Título" className="border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><input aria-label="URL da referência" value={ref.url||''} onChange={e=>setForm({...form,references:form.references.map((r:any,j:number)=>j===i?{...r,url:e.target.value}:r)})} placeholder="https://…" className="border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><input aria-label="O que a referência sustenta" value={ref.supports||''} onChange={e=>setForm({...form,references:form.references.map((r:any,j:number)=>j===i?{...r,supports:e.target.value}:r)})} placeholder="O que esta referência sustenta" className="border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><input aria-label="Data da verificação da referência" type="date" value={ref.verifiedAt||''} onChange={e=>setForm({...form,references:form.references.map((r:any,j:number)=>j===i?{...r,verifiedAt:e.target.value}:r)})} className="border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><button onClick={()=>setForm({...form,references:form.references.filter((_:any,j:number)=>j!==i)})} aria-label="Remover este item" className="p-2 text-[#8B2312]"><Trash2 size={15}/></button></div>)}<button onClick={()=>setForm({...form,references:[...form.references,{title:'',url:'',supports:'',verifiedAt:''}]})} className="text-sm border border-[#D8D1C9] rounded-xl px-3 py-2"><Plus size={14} className="inline mr-1"/>Referência</button></section><section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="font-medium text-sm mb-1">Links internos</div><p className="text-[12px] text-[#2B1B0A]/45 mb-3">Use só endereços deste site, como <code>/</code> ou <code>/blog/nome-do-artigo/</code>.</p>{form.internalLinks.map((link:any,i:number)=>{const destination=link.slug?`/blog/${link.slug}/`:(link.url||'');return <div key={i} className="grid grid-cols-1 md:grid-cols-[1fr_1fr_auto] gap-2 mb-2"><input aria-label="Texto do link interno" value={link.label||''} onChange={e=>setForm({...form,internalLinks:form.internalLinks.map((r:any,j:number)=>j===i?{...r,label:e.target.value}:r)})} placeholder="Texto do link" className="border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><input aria-label="Destino do link interno" value={destination} onChange={e=>setForm({...form,internalLinks:form.internalLinks.map((r:any,j:number)=>j===i?{label:r.label||'',url:e.target.value}:r)})} placeholder="/blog/outro-artigo/" className="border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><button onClick={()=>setForm({...form,internalLinks:form.internalLinks.filter((_:any,j:number)=>j!==i)})} aria-label="Remover este item" className="p-2 text-[#8B2312]"><Trash2 size={15}/></button></div>;})}<button onClick={()=>setForm({...form,internalLinks:[...form.internalLinks,{label:'',url:'/'}]})} className="text-sm border border-[#D8D1C9] rounded-xl px-3 py-2"><Plus size={14} className="inline mr-1"/>Link interno</button></section></div>
      <aside className="space-y-4"><section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="font-medium text-sm">Apresentação</div><select aria-label="Apresentação do artigo" value={form.presentation?.kind==='image'?form.presentation.image?.file:'none'} onChange={e=>setPresentation(e.target.value)} className="mt-2 w-full rounded-xl border border-[#D8D1C9] px-2 py-2 text-sm"><option value="none">Sem imagem adequada</option>{data.assets.map((asset:any)=><option key={asset.file} value={asset.file}>{asset.label}</option>)}</select>{form.presentation?.kind==='image'?<><label className="block mt-3 text-[11px] uppercase text-[#2B1B0A]/45">Alt</label><input aria-label="Texto alternativo da imagem" value={form.presentation.image.alt||''} onChange={e=>setForm({...form,presentation:{...form.presentation,image:{...form.presentation.image,alt:e.target.value}}})} className="mt-1 w-full border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><label className="block mt-3 text-[11px] uppercase text-[#2B1B0A]/45">Legenda</label><textarea aria-label="Legenda da imagem" value={form.presentation.image.caption||''} onChange={e=>setForm({...form,presentation:{...form.presentation,image:{...form.presentation.image,caption:e.target.value}}})} rows={3} className="mt-1 w-full border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/></>:<><label className="block mt-3 text-[11px] uppercase text-[#2B1B0A]/45">Motivo</label><textarea aria-label="Motivo para não usar imagem" value={form.presentation.reason||''} onChange={e=>setForm({...form,presentation:{...form.presentation,reason:e.target.value}})} rows={3} className="mt-1 w-full border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/></>}</section><section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><label className="text-[11px] uppercase text-[#2B1B0A]/45">Nota da alteração</label><textarea aria-label="Nota da alteração" value={form.changeNote} onChange={e=>setForm({...form,changeNote:e.target.value})} rows={3} className="mt-1 w-full border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><button disabled={busy} onClick={()=>void save()} className="mt-3 w-full inline-flex justify-center items-center gap-2 bg-[#222D19] text-white rounded-xl px-3 py-2.5 text-sm font-medium disabled:opacity-50"><Save size={15}/>Salvar como nova versão</button><p className="mt-2 text-[11px] text-[#2B1B0A]/45">Salvar não publica. Cada alteração vira uma nova versão, que precisa ser aprovada de novo.</p></section><button disabled={busy||!detail.approvals?.editorial||!detail.approvals?.clinical} onClick={()=>void exportSnapshot()} className="w-full inline-flex justify-center items-center gap-2 bg-white border border-[#D8D1C9] rounded-xl px-3 py-2.5 text-sm disabled:opacity-50"><Download size={15}/>Baixar versão aprovada (arquivo)</button></aside></div>}
    {mode==='history'&&<div className="grid grid-cols-1 lg:grid-cols-2 gap-4"><section className="bg-white border border-[#E4DFD9] rounded-2xl overflow-hidden"><div className="p-3 font-medium text-sm border-b border-[#E4DFD9]">Histórico de versões</div>{detail.versions.map((v:any)=><div key={v.id} className="p-3 border-b border-[#E4DFD9] last:border-0"><div className="flex justify-between"><span className="font-medium">v{v.version_number} · {v.title}</span><span className="text-[11px] text-[#2B1B0A]/45">{formatDate(v.created_at)}</span></div><details className="mt-1 text-[11px] text-[#2B1B0A]/45"><summary>Detalhes da versão</summary><div>Conteúdo: {v.content_sha256||'Indisponível'}</div><div>Apresentação: {v.presentation_sha256||'Indisponível'}</div></details><div className="text-[12px] mt-1">{v.change_note||'Sem nota de alteração.'}</div></div>)}</section><section className="bg-white border border-[#E4DFD9] rounded-2xl overflow-hidden"><div className="p-3 font-medium text-sm border-b border-[#E4DFD9]">Revisões registradas</div>{detail.reviews.map((r:any)=><div key={r.id} className="p-3 border-b border-[#E4DFD9] last:border-0"><div className="flex justify-between"><span className="font-medium">{r.review_type==='clinical'?'Clínica':'Editorial'} · {r.status==='approved'?'Aprovada':'Correções solicitadas'}</span><span className="text-[11px] text-[#2B1B0A]/45">{formatDate(r.reviewed_at)}</span></div><details className="text-[12px] mt-1"><summary>Identidade e versão registradas</summary><div>Versão: {detail.versions.find((v:any)=>v.id===r.article_version_id)?.version_number??'Indisponível'}</div><div>Responsável informado: {r.reviewer_name||'não informado'}</div><div>Operador que registrou: {r.recorded_by_user_id||'Indisponível'}</div></details><div className="text-[12px] text-[#2B1B0A]/60 mt-1">{r.notes||'Sem observação.'}</div></div>)}{!detail.reviews.length&&<div className="p-5 text-sm text-[#2B1B0A]/45">Nenhuma revisão registrada.</div>}</section></div>}
    {mode==='sources'&&<div className="space-y-3">{detail.sources.map((source:any)=><section key={source.id} className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="flex gap-3"><div><div className="font-medium">{source.source_title||source.source_slug||source.external_id}</div><div className="text-[12px] text-[#2B1B0A]/45 mt-1">Número no site antigo: {source.external_id} · {source.has_text?'texto disponível':'sem texto disponível'}</div></div><button onClick={()=>void openSource(source.id)} className="ml-auto text-sm border border-[#D8D1C9] rounded-xl px-3 py-2">Ler fonte</button></div><p className="text-sm text-[#2B1B0A]/65 mt-3 whitespace-pre-line">{source.body_excerpt}</p></section>)}{sourceDetail&&<section className="bg-white border border-[#565E48]/30 rounded-2xl p-4"><div className="flex"><div className="font-serif text-xl">{sourceDetail.source_title}</div><button aria-label="Fechar fonte legado" onClick={()=>setSourceDetail(null)} className="ml-auto"><X size={16}/></button></div><div className="text-[12px] text-[#2B1B0A]/45 mt-1">Publicada: {formatDate(sourceDetail.published_at_source)} · atualizada: {formatDate(sourceDetail.modified_at_source)}</div><div className="mt-4 max-h-[50vh] overflow-y-auto whitespace-pre-line text-sm leading-6 text-[#2B1B0A]/80">{sourceDetail.normalized_body_text||'Fonte sem texto disponível.'}</div></section>}</div>}
    </div></div></div>;
}

function OverviewSection({go}:{go:(s:BlogSection,status?:string)=>void}){
  const [data,setData]=useState<any>(null);const [error,setError]=useState('');const [loading,setLoading]=useState(true);const load=async()=>{setLoading(true);setError('');try{setData((await blogAdminGet({view:'overview'})).overview);}catch(e){setError(e instanceof Error?e.message:'Visão geral indisponível');}finally{setLoading(false);}};useEffect(()=>{void load();},[]);
  const cards=[['articles','Artigos no acervo',data?.counts?.articles,'articles',''],['published','Publicados',data?.counts?.published,'articles','published'],['drafts','Rascunhos privados',data?.counts?.drafts,'generate','drafts'],['review','Aguardando revisão',data?.counts?.review_pending,'review','review_pending'],['approved','Aprovados, aguardando publicação',data?.counts?.approved_waiting_publication,'articles','aprovado'],['indexed','Páginas indexadas no Google',data?.counts?.indexed,'automations','indexed'],['action','Pendências no Google',data?.counts?.action_pending,'automations','action_pending'],['publishPending','Publicações na fila',data?.counts?.publication_pending,'automations',''],['publishAttention','Publicações com problema',data?.counts?.publication_attention,'automations','']] as const;
  return <div className="space-y-4"><div className="flex justify-between items-start"><div><h2 className="font-serif text-2xl text-[#222D19]">Operação editorial</h2><p className="text-sm text-[#2B1B0A]/55 mt-1">Artigos, revisões e situação no Google. Quando um dado não pôde ser lido, aparece como indisponível, nunca como zero.</p></div><button aria-label="Atualizar visão geral" onClick={()=>void load()} className="p-2 rounded-xl border border-[#D8D1C9] bg-white"><RefreshCw size={15} className={loading?'animate-spin':''}/></button></div>{error&&<Notice type="error">{error}</Notice>}<div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-3">{cards.map(([key,labelText,value,target,status])=><button key={key} onClick={()=>go(target as BlogSection,status)} className="text-left bg-white border border-[#E4DFD9] rounded-2xl p-4 hover:border-[#565E48]/40"><div className="text-[11px] uppercase tracking-wide text-[#2B1B0A]/45">{labelText}</div><div className="font-serif text-3xl mt-2 text-[#222D19]">{countValue(value)}</div></button>)}</div><section className="bg-white border border-[#E4DFD9] rounded-2xl p-4 space-y-3"><div className="text-sm">Acompanhamento no Google: {data?.automation?data.automation.operator_paused?'Pausado':'Ativo':'Indisponível'}</div><div className="text-sm">Última verificação registrada: {formatDate(data?.last_run?.updated_at)} · {data?.last_run?.status||'Indisponível'}</div><div className="text-sm">Última verificação automática: {formatDate(data?.last_scheduled_run?.updated_at)} · {data?.last_scheduled_run?.status||'Indisponível'}</div><div className="text-sm">Próxima inspeção: {formatDate(data?.next_inspection_at)}</div><div className="text-[11px] text-[#2B1B0A]/40">Dados atualizados: {formatDate(data?.data_updated_at)}</div></section></div>;
}

function ArticlesSection(){
  const [mode,setMode]=useState<'articles'|'sources'>('articles');const [q,setQ]=useState('');const [status,setStatus]=useState(()=>new URLSearchParams(window.location.search).get('blogStatus')||'');const [page,setPage]=useState(1);const [data,setData]=useState<any>(null);const [error,setError]=useState('');const [selected,setSelected]=useState<string|null>(()=>new URLSearchParams(window.location.search).get('blogArticle'));const [source,setSource]=useState<any>(null);const load=async(target=page)=>{setError('');try{const json=await blogAdminGet({view:mode,q,status:mode==='articles'&&status!=='published'?status:undefined,publication:mode==='articles'&&status==='published'?'published':undefined,page:target,pageSize:20});setData(json);setPage(target);}catch(e){setError(e instanceof Error?e.message:'Falha ao carregar acervo');}};useEffect(()=>{void load(1);},[mode,status]);
  const total=data?.total;const hasNext=typeof total==='number'?page*20<total:(data?.items?.length||0)===20;const search=()=>void load(1);
  const openSource=async(id:string)=>{try{setSource((await blogAdminGet({view:'source',id})).source);}catch(e){setError(e instanceof Error?e.message:'Falha ao abrir fonte');}};
  return <div className="space-y-4"><div className="flex flex-wrap gap-2"><button onClick={()=>setMode('articles')} className={`px-3 py-2 rounded-xl text-sm ${mode==='articles'?'bg-[#222D19] text-white':'bg-white border border-[#D8D1C9]'}`}>Artigos</button><button onClick={()=>setMode('sources')} className={`px-3 py-2 rounded-xl text-sm ${mode==='sources'?'bg-[#222D19] text-white':'bg-white border border-[#D8D1C9]'}`}>Acervo legado</button></div><div className="bg-white border border-[#E4DFD9] rounded-2xl p-3 flex flex-col md:flex-row gap-2"><div className="relative flex-1"><Search size={15} className="absolute left-3 top-3 text-[#2B1B0A]/40"/><input aria-label="Buscar no acervo" value={q} onChange={e=>setQ(e.target.value)} onKeyDown={e=>e.key==='Enter'&&search()} placeholder={mode==='articles'?'Buscar título ou tema':'Buscar por título, endereço ou número antigo'} className="w-full pl-9 pr-3 py-2.5 rounded-xl border border-[#D8D1C9]"/></div>{mode==='articles'&&<select aria-label="Filtrar artigos por status ou publicação" value={status} onChange={e=>{setStatus(e.target.value);const url=new URL(window.location.href);if(e.target.value)url.searchParams.set('blogStatus',e.target.value);else url.searchParams.delete('blogStatus');history.replaceState({},'',url);}} className="rounded-xl border border-[#D8D1C9] px-3 py-2.5 text-sm"><option value="">Todos os status</option><option value="published">Com versão publicada</option>{Object.entries(STATUS_LABELS).map(([value,labelText])=><option key={value} value={value}>{labelText}</option>)}</select>}<button onClick={search} className="rounded-xl bg-[#222D19] text-white px-4 py-2.5 text-sm">Buscar</button></div>{error&&<Notice type="error">{error}</Notice>}
    {mode==='articles'?<div className="bg-white border border-[#E4DFD9] rounded-2xl overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[900px] text-sm"><thead><tr className="bg-[#F6F0E9] text-left text-[11px] uppercase text-[#2B1B0A]/45"><th className="px-4 py-3">Artigo</th><th className="px-4 py-3">Status</th><th className="px-4 py-3">Trabalho</th><th className="px-4 py-3">Público</th><th className="px-4 py-3">Aprovações atuais</th><th className="px-4 py-3">Publicação</th><th className="px-4 py-3">Google</th></tr></thead><tbody className="divide-y divide-[#E4DFD9]">{(data?.items||[]).map((item:any)=><tr key={item.id} onClick={()=>setSelected(item.id)} className="cursor-pointer hover:bg-[#F6F0E9]/60"><td className="px-4 py-3"><div className="font-medium text-[#222D19]">{item.working_title}</div><div className="text-[11px] text-[#2B1B0A]/40">/{item.target_slug}</div></td><td className="px-4 py-3"><StatusPill status={item.status}/></td><td className="px-4 py-3">v{item.work_version??'—'}</td><td className="px-4 py-3">{item.public_version?`v${item.public_version}`:'não publicado'}</td><td className="px-4 py-3 text-[12px]">Editorial {item.approvals?.editorial?'✓':'—'} · Clínica {item.approvals?.clinical?'✓':'—'}</td><td className="px-4 py-3 text-[12px]">{item.publication_state||'Indisponível'}</td><td className="px-4 py-3 text-[12px]">{({indexed:'Indexada',excluded:'Não indexada',unknown_to_google:'Ainda desconhecida',inconclusive:'Sem resposta conclusiva'} as Record<string,string>)[item.gsc?.knowledge_state]||(item.gsc?.knowledge_state?'Em acompanhamento':'Sem dados')}</td></tr>)}{!(data?.items||[]).length&&<tr><td colSpan={7} className="px-4 py-8 text-center text-[#2B1B0A]/45">Nenhum artigo encontrado.</td></tr>}</tbody></table></div></div>:<div className="grid grid-cols-1 md:grid-cols-2 gap-3">{(data?.items||[]).map((item:any)=><button key={item.id} onClick={()=>void openSource(item.id)} className="text-left bg-white border border-[#E4DFD9] rounded-2xl p-4 hover:border-[#565E48]/40"><div className="flex gap-3"><Archive size={18} className="text-[#565E48] mt-0.5"/><div><div className="font-medium">{item.source_title||item.source_slug||item.external_id}</div><div className="text-[11px] text-[#2B1B0A]/45 mt-1">ID {item.external_id} · {item.has_text?'texto disponível':'sem texto: geração bloqueada'}</div></div></div><p className="mt-3 text-sm text-[#2B1B0A]/60 line-clamp-3">{item.normalized_excerpt||item.body_excerpt||'Sem resumo.'}</p></button>)}</div>}
    <div className="flex justify-between"><button disabled={page<=1} onClick={()=>void load(page-1)} className="px-3 py-2 rounded-xl border border-[#D8D1C9] bg-white disabled:opacity-40"><ChevronLeft size={15} className="inline"/> Anterior</button><span className="text-sm text-[#2B1B0A]/45 self-center">Página {page}{typeof total==='number'?` · ${total} itens`:''}</span><button disabled={!hasNext} onClick={()=>void load(page+1)} className="px-3 py-2 rounded-xl border border-[#D8D1C9] bg-white disabled:opacity-40">Próxima <ChevronRight size={15} className="inline"/></button></div>
    {selected&&<ArticleDetail articleId={selected} onClose={()=>setSelected(null)} onSaved={()=>void load(page)}/>} {source&&<div role="dialog" aria-modal="true" aria-label="Artigo privado" tabIndex={-1} className="fixed inset-0 z-50 bg-black/35 p-4 overflow-y-auto"><div className="max-w-4xl mx-auto bg-[#F6F0E9] rounded-2xl p-5 border border-[#D8D1C9]"><div className="flex"><div><div className="font-serif text-2xl">{source.source_title}</div><div className="text-[12px] text-[#2B1B0A]/45">Número no site antigo: {source.external_id} · {formatDate(source.published_at_source)}</div></div><button aria-label="Fechar fonte legado" onClick={()=>setSource(null)} className="ml-auto p-2"><X size={17}/></button></div><div className="mt-5 bg-white border border-[#E4DFD9] rounded-xl p-4 whitespace-pre-line text-sm leading-6 max-h-[70vh] overflow-y-auto">{source.normalized_body_text||'Fonte sem texto disponível.'}</div></div></div>}
  </div>;
}

function GenerateSection(){
  const [sourceQuery,setSourceQuery]=useState('');const [sources,setSources]=useState<any[]>([]);const [selected,setSelected]=useState<any>(null);const [objective,setObjective]=useState('Criar um artigo útil e clinicamente prudente a partir da fonte legado e das referências verificadas.');const [intent,setIntent]=useState('Informacional');const [contribution,setContribution]=useState('Atualizar e organizar o conteúdo legado com foco em clareza e próximos passos seguros.');const [links,setLinks]=useState<string[]>(['/']);const [refs,setRefs]=useState<any[]>([{title:'',url:'',supports:'',verifiedAt:''}]);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [notice,setNotice]=useState('');const [draft,setDraft]=useState<any>(null);const [presentation,setPresentation]=useState<any>({kind:'none',reviewStatus:'reviewed',subject:'sem-imagem-adequada',reason:'Sem imagem adequada selecionada para esta pauta.',image:null});const [assets,setAssets]=useState<any[]>([]);const [drafts,setDrafts]=useState<any[]>([]);const [draftPage,setDraftPage]=useState(1);const [draftTotal,setDraftTotal]=useState<number|null>(null);const [draftQuery,setDraftQuery]=useState('');const [draftsReady,setDraftsReady]=useState(false);const [unresolvedKeys,setUnresolvedKeys]=useState<string[]>(()=>{try{return JSON.parse(localStorage.getItem('karyne_blog_generation:pending')||'[]');}catch{return [];}});const [operationKey,setOperationKey]=useState(()=>{try{return JSON.parse(localStorage.getItem('karyne_blog_generation:last')||'{}').operationKey||'';}catch{return '';}});
  const searchSources=async()=>{setError('');try{const json=await blogAdminGet({view:'sources',q:sourceQuery,page:1,pageSize:12});setSources(json.items||[]);}catch(e){setError(e instanceof Error?e.message:'Falha ao buscar fontes');}};
  const track=(key:string,status:string)=>{if(!key)return;setUnresolvedKeys(current=>{const next=['pending','uncertain','generating'].includes(status)?Array.from(new Set([...current,key])):current.filter(value=>value!==key);localStorage.setItem('karyne_blog_generation:pending',JSON.stringify(next));return next;});};
  const listDrafts=async(targetPage=1)=>{setDraftsReady(false);try{const result=await blogAdminGet({view:'drafts',q:draftQuery,page:targetPage,pageSize:12});setDrafts(result.items||[]);for(const row of result.items||[])track(row.operation_key,row.status);setDraftPage(targetPage);setDraftTotal(typeof result.total==='number'?result.total:null);setDraftsReady(true);}catch(e){setError(e instanceof Error?e.message:'Não foi possível recuperar os rascunhos privados.');}};
  const remember=(key:string)=>{setOperationKey(key);localStorage.setItem('karyne_blog_generation:last',JSON.stringify({operationKey:key}));};
  const reconcileKey=async(key:string)=>{if(!key)return;setError('');try{const result=await fetchEditorialDraft(key);if(result?.draft){track(key,result.draft.status);setDraft(result.draft);setNotice('Resultado da geração recuperado. Nenhuma nova geração foi feita.');}else{track(key,'uncertain');setDraft({operation_key:key,status:'uncertain'});setNotice('Ainda não deu para confirmar o resultado. Verifique de novo daqui a pouco.');}}catch(e){track(key,'uncertain');setDraft((current:any)=>current||{operation_key:key,status:'uncertain'});setError(e instanceof Error?e.message:'Falha ao consultar operação existente.');}};
  useEffect(()=>{void searchSources();void listDrafts();void blogAdminGet({view:'assets'}).then(j=>setAssets(j.assets||[])).catch(()=>{});if(operationKey){track(operationKey,'pending');setDraft({operation_key:operationKey,status:'pending'});void reconcileKey(operationKey);}},[]);

  const requestShape=useMemo(()=>selected?{sourceId:String(selected.external_id),briefing:{objective,searchIntent:intent,editorialContribution:contribution,allowedInternalLinks:links.filter(Boolean)},references:refs}:null,[selected,objective,intent,contribution,links,refs]);
  const payload=draft?.payload_json||draft?.draft||draft;const status=draft?.status||payload?.status;const pendingStatuses=['pending','uncertain','generating'];const unresolved=unresolvedKeys.length>0||pendingStatuses.includes(status)||drafts.some(row=>pendingStatuses.includes(row.status));
  const generate=async(forceNew=false)=>{if(busy||!selected||!requestShape||!draftsReady||unresolved||(forceNew&&status!=='failed')||(!forceNew&&status==='failed')||(!forceNew&&status==='draft'&&!draft?.promoted_article_id))return;setBusy(true);setError('');setNotice('');const key=persistentOperation(`generate:${selected.external_id}`,requestShape,forceNew);remember(key);track(key,'pending');setDraft({operation_key:key,status:'pending'});try{const result=await generateEditorialDraft({...requestShape,operationKey:key});const resolved=result.draft;if(resolved){setDraft(resolved);track(key,resolved.status||'uncertain');}else if(result.pending)setDraft({operation_key:key,status:'uncertain'});else {setDraft({...result,operation_key:key,status:result.status||'uncertain'});track(key,result.status||'uncertain');}setNotice(result.pending?'A geração ainda não terminou. Verifique o resultado antes de continuar.':result.reused?'Rascunho já existente recuperado, sem nova cobrança.':'Rascunho salvo. Ele é privado e ainda precisa de revisão.');await listDrafts(draftPage);}catch(e){if(e instanceof Error&&(e as Error&{generationNotStarted?:boolean}).generationNotStarted===true){track(key,'failed');setDraft({operation_key:key,status:'failed',last_error_code:e.message});localStorage.removeItem('karyne_blog_generation:last');clearOperation(`generate:${selected.external_id}`);setError(e.message);setNotice('A geração não começou. Corrija os dados e tente de novo.');}else{track(key,'uncertain');setDraft({operation_key:key,status:'uncertain'});setError(e instanceof Error?e.message:'Geração não confirmada');await reconcileKey(key);}await listDrafts(draftPage);}finally{setBusy(false);}};
  const reconcile=async()=>{setBusy(true);try{await reconcileKey(operationKey);await listDrafts(draftPage);}finally{setBusy(false);}};
  const recover=async(row:any)=>{if(busy)return;remember(row.operation_key);setDraft(row);setBusy(true);try{await reconcileKey(row.operation_key);}finally{setBusy(false);}};
  const choosePresentation=(value:string)=>{if(value==='none')setPresentation({kind:'none',reviewStatus:'reviewed',subject:'sem-imagem-adequada',reason:'Sem imagem adequada selecionada para esta pauta.',image:null});else{const asset=assets.find(a=>a.file===value);setPresentation({kind:'image',reviewStatus:'reviewed',subject:asset.label,image:{file:asset.file,label:asset.label,alt:asset.defaultAlt,caption:asset.defaultCaption||''}});}};
  const promote=async()=>{if(!operationKey||draft?.promoted_article_id)return;setBusy(true);setError('');try{const op=persistentOperation(`promote:${operationKey}`,{operationKey,presentation});const result=await blogAdminPost({action:'promote-draft',draftOperationKey:operationKey,operationKey:op,presentation});setDraft({...draft,status:'promoted',promoted_article_id:result.result.articleId});await listDrafts(draftPage);setNotice(`Artigo criado (versão ${result.result.versionNumber}). Ele é privado e foi para a revisão editorial.`);}catch(e){setError(e instanceof Error?e.message:'Falha ao criar versão editável');}finally{setBusy(false);}};
  return <div className="grid grid-cols-1 xl:grid-cols-[380px_1fr] gap-4"><aside className="space-y-4"><section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="font-medium">1. Fonte legado</div><div className="mt-3 flex gap-2"><input aria-label="Buscar fonte legado" value={sourceQuery} onChange={e=>setSourceQuery(e.target.value)} className="flex-1 rounded-xl border border-[#D8D1C9] px-3 py-2" placeholder="Buscar fonte"/><button aria-label="Buscar fonte legado" onClick={()=>void searchSources()} className="p-2 border border-[#D8D1C9] rounded-xl"><Search size={15}/></button></div><div className="mt-3 max-h-72 overflow-y-auto space-y-2">{sources.map(item=><button key={item.id} disabled={!item.has_text} onClick={()=>setSelected(item)} className={`w-full text-left rounded-xl border p-3 ${selected?.id===item.id?'border-[#565E48] bg-[#565E48]/8':'border-[#E4DFD9]'} disabled:opacity-45`}><div className="text-sm font-medium">{item.source_title||item.external_id}</div><div className="text-[11px] text-[#2B1B0A]/45">ID {item.external_id} · {item.has_text?'pronta para geração':'sem texto: bloqueada'}</div></button>)}</div></section><section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="font-medium">Uso de IA</div><p className="text-[12px] text-[#2B1B0A]/55 mt-2">Cada geração usa créditos de IA. Ela só acontece quando você clica, e se a resposta se perder o painel não tenta de novo sozinho, para não cobrar duas vezes.</p><button disabled={busy||!selected?.has_text||!draftsReady||unresolved||status==='failed'||(status==='draft'&&!draft?.promoted_article_id)} onClick={()=>void generate(false)} className="mt-3 w-full bg-[#222D19] text-white rounded-xl px-3 py-2.5 text-sm font-medium disabled:opacity-40"><Bot size={15} className="inline mr-2"/>Gerar rascunho com IA</button></section></aside>
    <main className="space-y-4">{error&&<Notice type="error">{error}</Notice>}{notice&&<Notice type="ok">{notice}</Notice>}<section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><h2 className="font-medium">Rascunhos privados salvos</h2>{unresolvedKeys.length>0&&<div className="mt-3 rounded-xl border border-[#D8D1C9] bg-[#F6F0E9] p-3 text-sm"><p>Há {unresolvedKeys.length} {unresolvedKeys.length===1?'geração a conferir':'gerações a conferir'}. Novas gerações ficam bloqueadas até você conferir o resultado.</p><div className="flex flex-wrap gap-2 mt-2">{unresolvedKeys.map((key,index)=><button key={key} disabled={busy} onClick={()=>void recover({operation_key:key,status:'uncertain'})} className="border border-[#D8D1C9] rounded-xl bg-white px-3 py-2 disabled:opacity-40">Verificar geração {index+1}</button>)}</div></div>}<p className="mt-1 text-[12px] text-[#2B1B0A]/55">Os rascunhos gerados ficam guardados aqui e abrem em qualquer computador. Nenhum deles é publicado.</p><div className="flex gap-2 mt-3"><input aria-label="Buscar rascunhos privados" value={draftQuery} onChange={e=>setDraftQuery(e.target.value)} onKeyDown={e=>e.key==='Enter'&&void listDrafts(1)} placeholder="Buscar rascunho" className="flex-1 border border-[#D8D1C9] rounded-xl px-3 py-2"/><button onClick={()=>void listDrafts(1)} className="border border-[#D8D1C9] rounded-xl px-3 py-2 text-sm">Buscar</button></div><div className="mt-3 space-y-2">{drafts.map(row=><button key={row.operation_key} disabled={busy} onClick={()=>void recover(row)} className="w-full text-left rounded-xl border border-[#E4DFD9] p-3 disabled:opacity-40"><div className="font-medium text-sm">{row.payload_json?.workingTitle||'Geração sem título confirmado'}</div><div className="text-[12px] text-[#2B1B0A]/50">{row.status==='draft'?'Rascunho privado':row.status==='failed'?'Falha confirmada':row.status==='uncertain'?'Resultado incerto':row.status==='generating'||row.status==='pending'?'Em andamento':row.status==='promoted'?'Já virou artigo':row.status} · {formatDate(row.created_at)}{row.promoted_article_id?' · já virou artigo':''}</div></button>)}</div>{draftsReady&&!drafts.length&&<p className="mt-3 text-sm text-[#2B1B0A]/50">Nenhum rascunho encontrado.</p>}<div className="flex justify-between mt-3 text-sm"><button disabled={busy||draftPage<=1} onClick={()=>void listDrafts(draftPage-1)} className="px-3 py-2 border border-[#D8D1C9] rounded-xl disabled:opacity-40">Anterior</button><span>Página {draftPage}</span><button disabled={busy||(draftTotal!==null?draftPage*12>=draftTotal:drafts.length<12)} onClick={()=>void listDrafts(draftPage+1)} className="px-3 py-2 border border-[#D8D1C9] rounded-xl disabled:opacity-40">Próxima</button></div></section><section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="font-medium">2. Briefing</div><label className="block mt-3 text-[11px] uppercase text-[#2B1B0A]/45">Objetivo</label><textarea aria-label="Objetivo do artigo" value={objective} onChange={e=>setObjective(e.target.value)} rows={3} className="mt-1 w-full rounded-xl border border-[#D8D1C9] px-3 py-2"/><div className="grid grid-cols-1 md:grid-cols-2 gap-3 mt-3"><div><label className="text-[11px] uppercase text-[#2B1B0A]/45">Intenção de busca</label><input aria-label="Intenção de busca" value={intent} onChange={e=>setIntent(e.target.value)} className="mt-1 w-full rounded-xl border border-[#D8D1C9] px-3 py-2"/></div><div><label className="text-[11px] uppercase text-[#2B1B0A]/45">Contribuição editorial</label><input aria-label="Contribuição editorial" value={contribution} onChange={e=>setContribution(e.target.value)} className="mt-1 w-full rounded-xl border border-[#D8D1C9] px-3 py-2"/></div></div><label className="block mt-3 text-[11px] uppercase text-[#2B1B0A]/45">Links internos permitidos</label>{links.map((link,i)=><div className="flex gap-2 mt-1" key={i}><input aria-label="Link interno permitido" value={link} onChange={e=>setLinks(links.map((v,j)=>j===i?e.target.value:v))} className="flex-1 rounded-xl border border-[#D8D1C9] px-3 py-2" placeholder="/ ou /blog/slug/"/><button onClick={()=>setLinks(links.filter((_,j)=>j!==i))} aria-label="Remover este item" className="p-2 text-[#8B2312]"><Trash2 size={15}/></button></div>)}<button onClick={()=>setLinks([...links,''])} className="mt-2 text-sm border border-[#D8D1C9] rounded-xl px-3 py-2"><Plus size={14} className="inline mr-1"/>Link permitido</button></section>
    <section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="font-medium">3. Referências verificadas</div><p className="text-[12px] text-[#2B1B0A]/50 mt-1">Para cada referência, diga o que ela comprova e quando você conferiu o link. A IA só pode usar estas referências.</p>{refs.map((ref,i)=><div key={i} className="mt-3 rounded-xl bg-[#FAF8F4] border border-[#E4DFD9] p-3 grid grid-cols-1 md:grid-cols-2 gap-2"><input aria-label="Título da referência" value={ref.title} onChange={e=>setRefs(refs.map((r,j)=>j===i?{...r,title:e.target.value}:r))} placeholder="Título" className="border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><input aria-label="URL da referência" value={ref.url} onChange={e=>setRefs(refs.map((r,j)=>j===i?{...r,url:e.target.value}:r))} placeholder="https://…" className="border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><input aria-label="O que a referência sustenta" value={ref.supports} onChange={e=>setRefs(refs.map((r,j)=>j===i?{...r,supports:e.target.value}:r))} placeholder="O que esta referência sustenta" className="border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><div className="flex gap-2"><input aria-label="Data da verificação da referência" type="date" value={ref.verifiedAt} onChange={e=>setRefs(refs.map((r,j)=>j===i?{...r,verifiedAt:e.target.value}:r))} className="flex-1 border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><button onClick={()=>setRefs(refs.filter((_,j)=>j!==i))} aria-label="Remover este item" className="p-2 text-[#8B2312]"><Trash2 size={15}/></button></div></div>)}<button onClick={()=>setRefs([...refs,{title:'',url:'',supports:'',verifiedAt:''}])} className="mt-2 text-sm border border-[#D8D1C9] rounded-xl px-3 py-2"><Plus size={14} className="inline mr-1"/>Referência</button></section>
    {(draft||operationKey)&&<section className="space-y-4"><div className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="flex flex-wrap gap-3 justify-between"><div><div className="font-serif text-2xl">{payload?.workingTitle||'Geração com IA'}</div><div className="text-[12px] text-[#2B1B0A]/45 mt-1">Estado: {status==='failed'?'Falha confirmada':status==='draft'?'Rascunho privado':status==='uncertain'?'Resultado incerto':status==='pending'||status==='generating'?'Em andamento':status==='promoted'?'Já virou artigo':'Indisponível'} · IA: {payload?.generator?.provider||'não informada'} · modelo: {payload?.generator?.model||'não informado'} · custo: {payload?.generator?.billableUsage&&payload.generator.billableUsage!=='nao_confirmado'?payload.generator.billableUsage:'não confirmado'}</div></div>{status==='failed'&&<button disabled={busy||unresolved||!selected?.has_text} onClick={()=>void generate(true)} className="border border-[#D8D1C9] rounded-xl px-3 py-2 text-sm">Tentar de novo (a anterior falhou)</button>}{pendingStatuses.includes(status)&&<button disabled={busy} onClick={()=>void reconcile()} className="border border-[#D8D1C9] rounded-xl px-3 py-2 text-sm">Verificar resultado da geração</button>}</div></div><div className="text-sm text-[#2B1B0A]/60">{draft?.last_error_code&&`Última falha: ${draft.last_error_code}`}{draft?.promoted_article_id&&'Este rascunho já virou um artigo para edição.'}</div>{payload?.workingTitle&&<PreviewArticle article={{title:payload.workingTitle,description:payload.description,body:payload.body,references:payload.references,internalLinks:payload.internalLinks,ctaLabel:payload.ctaLabel}} presentation={presentation}/>}{status==='draft'&&!draft?.promoted_article_id&&<div className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="font-medium">4. Imagem e criação do artigo</div><p className="text-[12px] text-[#2B1B0A]/50 mt-1">Escolha a imagem você mesmo. O painel não gera nem baixa imagens.</p><select aria-label="Apresentação do rascunho" value={presentation.kind==='image'?presentation.image.file:'none'} onChange={e=>choosePresentation(e.target.value)} className="mt-3 rounded-xl border border-[#D8D1C9] px-3 py-2 text-sm"><option value="none">Sem imagem adequada</option>{assets.map(a=><option key={a.file} value={a.file}>{a.label}</option>)}</select>{presentation.kind==='image'&&<div className="grid grid-cols-1 md:grid-cols-2 gap-2 mt-2"><input aria-label="Texto alternativo da imagem" value={presentation.image.alt} onChange={e=>setPresentation({...presentation,image:{...presentation.image,alt:e.target.value}})} className="border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm" placeholder="Texto alternativo"/><input aria-label="Legenda da imagem" value={presentation.image.caption} onChange={e=>setPresentation({...presentation,image:{...presentation.image,caption:e.target.value}})} className="border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm" placeholder="Legenda"/></div>}<button disabled={busy} onClick={()=>void promote()} className="mt-3 bg-[#222D19] text-white rounded-xl px-4 py-2.5 text-sm font-medium disabled:opacity-40"><FileEdit size={15} className="inline mr-2"/>Criar artigo para edição (privado)</button></div>}</section>}
    </main></div>;
}

function ReviewPanel({articleId,onClose,onDone}:{articleId:string;onClose:()=>void;onDone:()=>void}){
  useModalAccessibility(onClose);
  const [data,setData]=useState<any>(null);const [notes,setNotes]=useState('');const [clinicalName,setClinicalName]=useState('');const [evidence,setEvidence]=useState('');const [error,setError]=useState('');const [notice,setNotice]=useState('');const [busy,setBusy]=useState(false);const load=async()=>{try{setData(await blogAdminGet({view:'article',id:articleId}));}catch(e){setError(e instanceof Error?e.message:'Falha ao abrir revisão');}};useEffect(()=>{void load();},[articleId]);if(!data)return <div role="dialog" aria-modal="true" aria-label="Artigo privado" tabIndex={-1} className="fixed inset-0 z-50 bg-black/35 p-4"><div className="max-w-4xl mx-auto bg-[#F6F0E9] rounded-2xl p-5">{error||'Carregando…'}<button className="ml-3" onClick={onClose}>Fechar</button></div></div>;
  const detail=data.detail;const version=detail.versions[0];const payload=version.content_payload_json||{title:version.title,description:version.description,body:version.body_json,references:version.references_json};const presentation=version.presentation_payload_json;const publication=detail.publication||{};const intent=publication.intent?.intent||null;const publicationOp=publication.latestOperation||null;const criticalPublication=['reserved','preparing','publishing','verifying','uncertain'].includes(publicationOp?.status);const finalEditorial=Boolean(detail.approvals?.clinical&&!detail.approvals?.editorial);const finalClinical=Boolean(detail.approvals?.editorial&&!detail.approvals?.clinical);
  const chooseIntent=async(next:'auto'|'hold')=>{setBusy(true);setError('');setNotice('');try{const base={action:'set-publish-intent',versionId:version.id,contentSha256:version.content_sha256,presentationSha256:version.presentation_sha256,intent:next};const op=persistentOperation(`publish-intent:${version.id}:${next}`,base);const result=await blogAdminPost({...base,operationKey:op});clearOperation(`publish-intent:${version.id}:${next}`);setNotice(next==='auto'?'Esta versão será publicada assim que as duas revisões forem aprovadas.':'Esta versão não será publicada automaticamente.');if(result.result?.publicationOperationId)setNotice('As revisões já estavam aprovadas, então esta versão entrou na fila de publicação.');await load();onDone();}catch(e){setError(e instanceof Error?e.message:'Intenção de publicação não registrada');}finally{setBusy(false);}};
  const queuePublication=async()=>{setBusy(true);setError('');setNotice('');try{const base={action:'queue-publication',articleId:detail.article.id,versionId:version.id,contentSha256:version.content_sha256,presentationSha256:version.presentation_sha256};const op=persistentOperation(`queue-publication:${version.id}`,base);await blogAdminPost({...base,operationKey:op});clearOperation(`queue-publication:${version.id}`);setNotice('Esta versão entrou na fila de publicação. Ela só aparece como publicada depois que o painel confirmar a página no ar.');await load();onDone();}catch(e){setError(e instanceof Error?e.message:'Publicação não enfileirada');}finally{setBusy(false);}};
  const retryPublication=async()=>{if(!publicationOp?.id)return;setBusy(true);setError('');setNotice('');try{const base={action:'retry-publication',publicationOperationId:publicationOp.id};const op=persistentOperation(`retry-publication:${publicationOp.id}:${publicationOp.attempts}`,base,true);await blogAdminPost({...base,operationKey:op});setNotice('Nova tentativa de publicação registrada.');await load();onDone();}catch(e){setError(e instanceof Error?e.message:'Nova tentativa não registrada');}finally{setBusy(false);}};
  const act=async(reviewType:'editorial'|'clinical',decision:'approved'|'changes_requested')=>{if(decision==='approved'&&!intent){setError('Antes de aprovar, escolha se esta versão deve ser publicada automaticamente ou ficar aprovada sem publicar.');return;}setBusy(true);setError('');setNotice('');try{const base={action:'review',versionId:version.id,contentSha256:version.content_sha256,presentationSha256:version.presentation_sha256,reviewType,decision,reviewerName:reviewType==='clinical'?clinicalName:'',notes,evidence:reviewType==='clinical'&&evidence?{clinical_evidence:evidence}:{}};const op=persistentOperation(`review:${version.id}:${reviewType}:${decision}`,base);const result=await blogAdminPost({...base,operationKey:op});clearOperation(`review:${version.id}:${reviewType}:${decision}`);const willPublish=decision==='approved'&&intent==='auto'&&Boolean(result.result?.publicationOperationId);setNotice(willPublish?'Aprovação registrada. Esta versão entrou na fila de publicação.':decision==='approved'?`${reviewType==='clinical'?'Aprovação clínica':'Aprovação editorial'} registrada para esta versão.`:'Pedido de correção registrado. Se esta versão estava na fila de publicação, ela saiu da fila.');await load();onDone();}catch(e){setError(e instanceof Error?e.message:'Revisão não registrada');}finally{setBusy(false);}};
  return <div role="dialog" aria-modal="true" aria-label="Artigo privado" tabIndex={-1} className="fixed inset-0 z-50 bg-black/35 p-3 md:p-6 overflow-y-auto"><div className="max-w-6xl mx-auto bg-[#F6F0E9] rounded-2xl border border-[#D8D1C9] overflow-hidden"><div className="p-4 border-b border-[#D8D1C9] flex"><div><div className="font-serif text-xl">Revisão · v{version.version_number}</div><details className="text-[11px] text-[#2B1B0A]/45"><summary>Detalhes da versão</summary><div>Conteúdo: {version.content_sha256||'Indisponível'}</div><div>Apresentação: {version.presentation_sha256||'Indisponível'}</div></details></div><button aria-label="Fechar artigo" onClick={onClose} className="ml-auto"><X size={17}/></button></div><div className="p-4 md:p-6 grid grid-cols-1 xl:grid-cols-[1fr_330px] gap-4"> <PreviewArticle article={payload} presentation={presentation}/><aside className="space-y-4">{error&&<Notice type="error">{error}</Notice>}{notice&&<Notice type="ok">{notice}</Notice>}<section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="font-medium">Depois das aprovações</div><p className="mt-1 text-[11px] text-[#2B1B0A]/45">A escolha vale só para esta versão. Se o texto for editado, será preciso escolher de novo.</p><div className="mt-3 grid grid-cols-1 gap-2"><button disabled={busy||criticalPublication} onClick={()=>void chooseIntent('auto')} className={`rounded-xl border px-3 py-2 text-left text-sm disabled:opacity-40 ${intent==='auto'?'border-[#565E48] bg-[#565E48]/10':'border-[#D8D1C9]'}`}><span className="font-medium">Publicar automaticamente</span><span className="block text-[11px] text-[#2B1B0A]/50">Publica esta versão assim que as revisões editorial e clínica forem aprovadas.</span></button><button disabled={busy||criticalPublication} onClick={()=>void chooseIntent('hold')} className={`rounded-xl border px-3 py-2 text-left text-sm disabled:opacity-40 ${intent==='hold'?'border-[#565E48] bg-[#565E48]/10':'border-[#D8D1C9]'}`}><span className="font-medium">Manter aprovado sem publicar</span><span className="block text-[11px] text-[#2B1B0A]/50">Depois de aprovada, alguém precisa clicar em "Publicar esta versão".</span></button></div><div className="mt-3 text-[12px] text-[#2B1B0A]/60">Situação: <strong>{publication.state||'Aguardando revisão'}</strong></div>{intent==='auto'&&publication.infrastructure_enabled===false&&<div className="mt-2 text-[11px] text-[#8B5B12]">A publicação automática ainda não foi ligada no servidor. Até lá, versões marcadas para publicar ficam aguardando na fila.</div>}{detail.approvals?.editorial&&detail.approvals?.clinical&&(!publicationOp||['cancelled'].includes(publicationOp.status))&&<button disabled={busy||criticalPublication} onClick={()=>void queuePublication()} className="mt-3 w-full rounded-xl bg-[#222D19] px-3 py-2.5 text-sm font-medium text-white disabled:opacity-40">Publicar esta versão</button>}{publicationOp&&['failed','blocked'].includes(publicationOp.status)&&<button disabled={busy||publicationOp.attempts>=3} onClick={()=>void retryPublication()} className="mt-3 w-full rounded-xl border border-[#D8D1C9] px-3 py-2.5 text-sm disabled:opacity-40">Tentar novamente ({publicationOp.attempts}/3)</button>}{publicationOp?.status==='uncertain'&&<div className="mt-3 text-[11px] text-[#8B5B12]">Não foi possível confirmar se a publicação terminou. Novas tentativas ficam bloqueadas até essa conferência ser feita.</div>}</section><section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="font-medium">Decisão editorial</div><label className="block mt-3 text-[11px] uppercase text-[#2B1B0A]/45">Comentário / correção</label><textarea aria-label="Comentário ou correção" value={notes} onChange={e=>setNotes(e.target.value)} rows={4} className="mt-1 w-full border border-[#D8D1C9] rounded-lg p-2 text-sm"/><div className="flex gap-2 mt-3"><button disabled={busy||notes.trim().length<3} onClick={()=>void act('editorial','changes_requested')} className="flex-1 border border-[#8B2312]/30 text-[#8B2312] rounded-xl px-2 py-2 text-sm disabled:opacity-40">Pedir correção</button><button disabled={busy||!intent||criticalPublication} onClick={()=>void act('editorial','approved')} className="flex-1 bg-[#222D19] text-white rounded-xl px-2 py-2 text-sm disabled:opacity-40">{intent==='auto'&&finalEditorial?'Aprovar e publicar':'Aprovar editorial'}</button></div></section><section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="font-medium">Aprovação clínica</div><p className="text-[11px] text-[#2B1B0A]/45 mt-1">O painel registra quem clicou. O nome abaixo é de quem fez a revisão clínica; clicar aqui não significa que foi a Dra. Karyne.</p><label className="block mt-3 text-[11px] uppercase text-[#2B1B0A]/45">Responsável clínico</label><input aria-label="Responsável clínico" value={clinicalName} onChange={e=>setClinicalName(e.target.value)} className="mt-1 w-full border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><label className="block mt-3 text-[11px] uppercase text-[#2B1B0A]/45">Comprovante da revisão (opcional)</label><input aria-label="Evidência da revisão clínica" value={evidence} onChange={e=>setEvidence(e.target.value)} className="mt-1 w-full border border-[#D8D1C9] rounded-lg px-2 py-2 text-sm"/><button disabled={busy||notes.trim().length<3} onClick={()=>void act('clinical','changes_requested')} className="mt-3 w-full border border-[#8B2312]/30 text-[#8B2312] rounded-xl px-2 py-2.5 text-sm disabled:opacity-40">Pedir correção clínica</button><button disabled={busy||clinicalName.trim().length<3||!intent||criticalPublication} onClick={()=>void act('clinical','approved')} className="mt-3 w-full bg-[#565E48] text-white rounded-xl px-2 py-2.5 text-sm font-medium disabled:opacity-40"><CheckCircle2 size={15} className="inline mr-2"/>{intent==='auto'&&finalClinical?'Aprovar clínica e publicar':'Registrar aprovação clínica'}</button></section><section className="bg-white border border-[#E4DFD9] rounded-2xl p-4"><div className="font-medium text-sm">Histórico desta versão</div>{detail.reviews.filter((r:any)=>r.article_version_id===version.id).map((r:any)=><div key={r.id} className="mt-2 text-[12px] border-t border-[#E4DFD9] pt-2"><div>{r.review_type==='clinical'?'Clínica':'Editorial'} · {r.status==='approved'?'Aprovada':r.status==='changes_requested'?'Correções pedidas':'Pendente'} · {formatDate(r.reviewed_at)}</div><details><summary>Identidade e versão registradas</summary><div>Versão: {version.version_number}</div><div>Responsável informado: {r.reviewer_name||'não informado'}</div><div>Operador que registrou: {r.recorded_by_user_id||'Indisponível'}</div></details><div className="text-[#2B1B0A]/50">{r.notes}</div></div>)}</section></aside></div></div></div>;
}

function ReviewSection(){const [data,setData]=useState<any>(null);const [selected,setSelected]=useState<string|null>(null);const [error,setError]=useState('');const load=async()=>{try{setData(await blogAdminGet({view:'review-queue',page:1,pageSize:50}));}catch(e){setError(e instanceof Error?e.message:'Fila indisponível');}};useEffect(()=>{void load();},[]);return <div className="space-y-4"><div><h2 className="font-serif text-2xl">Fila de revisão</h2><p className="text-sm text-[#2B1B0A]/55 mt-1">Cada aprovação vale só para a versão revisada. Se o texto mudar, ele volta para a fila.</p></div>{error&&<Notice type="error">{error}</Notice>}<div className="grid grid-cols-1 lg:grid-cols-2 gap-3">{(data?.items||[]).map((item:any)=><button key={item.id} onClick={()=>setSelected(item.id)} className="text-left bg-white border border-[#E4DFD9] rounded-2xl p-4 hover:border-[#565E48]/40"><div className="flex gap-3"><div className="flex-1"><div className="font-medium">{item.working_title}</div><div className="text-[12px] text-[#2B1B0A]/45 mt-1">v{item.work_version??'—'} · editorial {item.approvals?.editorial?'aprovada':'pendente'} · clínica {item.approvals?.clinical?'aprovada':'pendente'}</div></div><StatusPill status={item.status}/></div></button>)}</div>{data&&!(data.items||[]).length&&<Notice type="ok">Nenhum artigo pendente na fila atual.</Notice>}{selected&&<ReviewPanel articleId={selected} onClose={()=>setSelected(null)} onDone={()=>void load()}/>}</div>}

export const BlogHub:React.FC=()=>{
  const initial=(()=>{const value=new URLSearchParams(window.location.search).get('blogSection') as BlogSection|null;return SECTIONS.some(s=>s.id===value)?value!:'overview';})();
  const [section,setSection]=useState<BlogSection>(initial);const go=(next:BlogSection,status?:string)=>{const url=new URL(window.location.href);if(status)url.searchParams.set('blogStatus',status);else url.searchParams.delete('blogStatus');history.replaceState({},'',url);setSection(next);updateBlogSection(next);};
  return <div className="space-y-5 [&_button:focus-visible]:outline-2 [&_button:focus-visible]:outline-offset-2 [&_button:focus-visible]:outline-[#565E48] [&_input:focus-visible]:outline-2 [&_input:focus-visible]:outline-[#565E48] [&_textarea:focus-visible]:outline-2 [&_textarea:focus-visible]:outline-[#565E48] [&_select:focus-visible]:outline-2 [&_select:focus-visible]:outline-[#565E48] [&_a:focus-visible]:outline-2 [&_a:focus-visible]:outline-[#565E48] [&_summary:focus-visible]:outline-2 [&_summary:focus-visible]:outline-[#565E48]"><div className="bg-white border border-[#E4DFD9] rounded-2xl p-1.5 flex gap-1 overflow-x-auto">{SECTIONS.map(item=>{const Icon=item.icon;return <button key={item.id} onClick={()=>go(item.id)} className={`flex-none inline-flex items-center gap-2 px-3.5 py-2 rounded-xl text-sm font-medium ${section===item.id?'bg-[#222D19] text-white':'text-[#2B1B0A]/60 hover:bg-[#F6F0E9]'}`}><Icon size={15}/>{item.label}</button>;})}</div>{section==='overview'&&<OverviewSection go={go}/>} {section==='articles'&&<ArticlesSection/>} {section==='generate'&&<GenerateSection/>} {section==='review'&&<ReviewSection/>} {section==='automations'&&<div className="space-y-4"><BlogPublicationStatus/><BlogGscStatus/></div>}</div>;
};
